ius: 0.08\n  });\n  slide.addText(\"68%\", {\n    x: 3.65, y: 1.1, w: 2.9, h: 0.8,\n    fontSize: 40, fontFace: \"Georgia\", bold: true, color: C.accent, align: \"center\", margin: 0\n  });\n  slide.addText(\"of global bot traffic from\\ntop 10 countries\", {\n    x: 3.65, y: 1.85, w: 2.9, h: 0.7,\n    fontSize: 12, fontFace: \"Calibri\", color: C.light, align: \"center\", margin: 0\n  });\n\n  // Card 3 — 4.3% malicious emails\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 6.8, y: 1.1, w: 2.9, h: 1.5,\n    fill: { color: C.statBg }, rectRadius: 0.08\n  });\n  slide.addText(\"4.3%\", {\n    x: 6.8, y: 1.1, w: 2.9, h: 0.8,\n    fontSize: 40, fontFace: \"Georgia\", bold: true, color: C.teal, align: \"center\", margin: 0\n  });\n  slide.addText(\"of emails processed\\nwere malicious\", {\n    x: 6.8, y: 1.85, w: 2.9, h: 0.7,\n    fontSize: 12, fontFace: \"Calibri\", color: C.light, align: \"center\", margin: 0\n  });\n\n  // Bottom section — three info blocks\n  // Block 1 — Most attacked sector\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 2.9, w: 2.9, h: 1.65,\n    fill: { color: C.statBg }, rectRadius: 0.08\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 2.9, w: 2.9, h: 0.06,\n    fill: { color: C.red }\n  });\n  slide.addText(\"Most Attacked Sector\", {\n    x: 0.7, y: 3.05, w: 2.5, h: 0.35,\n    fontSize: 13, fontFace: \"Calibri\", bold: true, color: C.white, margin: 0\n  });\n  slide.addText(\"Gambling & Games\", {\n    x: 0.7, y: 3.4, w: 2.5, h: 0.3,\n    fontSize: 16, fontFace: \"Georgia\", bold: true, color: C.red, margin: 0\n  });\n  slide.addText(\"Leading industry category targeted by attacks throughout 2024\", {\n    x: 0.7, y: 3.75, w: 2.5, h: 0.65,\n    fontSize: 11, fontFace: \"Calibri\", color: C.light, margin: 0\n  });\n\n  // Block 2 — Log4j persistence\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 3.65, y: 2.9, w: 2.9, h: 1.65,\n    fill: { color: C.statBg }, rectRadius: 0.08\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 3.65, y: 2.9, w: 2.9, h: 0.06,\n    fill: { color: C.accent }\n  });\n  slide.addText(\"Log4j Still Exploited\", {\n    x: 3.85, y: 3.05, w: 2.5, h: 0.35,\n    fontSize: 13, fontFace: \"Calibri\", bold: true, color: C.white, margin: 0\n  });\n  slide.addText(\"CVE-2021-44228\", {\n    x: 3.85, y: 3.4, w: 2.5, h: 0.3,\n    fontSize: 16, fontFace: \"Georgia\", bold: true, color: C.accent, margin: 0\n  });\n  slide.addText(\"Actively targeted 3+ years after disclosure — underscoring persistent vulnerability risks\", {\n    x: 3.85, y: 3.75, w: 2.5, h: 0.65,\n    fontSize: 11, fontFace: \"Calibri\", color: C.light, margin: 0\n  });\n\n  // Block 3 — Email threats\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 6.8, y: 2.9, w: 2.9, h: 1.65,\n    fill: { color: C.statBg }, rectRadius: 0.08\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 6.8, y: 2.9, w: 2.9, h: 0.06,\n    fill: { color: C.teal }\n  });\n  slide.addText(\"Email Threats\", {\n    x: 7.0, y: 3.05, w: 2.5, h: 0.35,\n    fontSize: 13, fontFace: \"Calibri\", bold: true, color: C.white, margin: 0\n  });\n  slide.addText(\"43% with deceptive links\", {\n    x: 7.0, y: 3.4, w: 2.5, h: 0.3,\n    fontSize: 16, fontFace: \"Georgia\", bold: true, color: C.teal, margin: 0\n  });\n  slide.addText(\"Of malicious emails, 43% contained deceptive links. .bar TLD originated the most spam\", {\n    x: 7.0, y: 3.75, w: 2.5, h: 0.65,\n    fontSize: 11, fontFace: \"Calibri\", color: C.light, margin: 0\n  });\n\n  // RPKI note\n  slide.addText(\"RPKI valid routes increased by 6.4% — progress toward improved Internet routing security\", {\n    x: 0.5, y: 4.75, w: 9.0, h: 0.3,\n    fontSize: 11, fontFace: \"Calibri\", color: C.midGray, margin: 0\n  });\n}\n\n// ─────────────────────────────────────────────\n// SLIDE 7 — Five Takeaways Shaping the 2025 Internet Outlook\n// ─────────────────────────────────────────────\n{\n  const slide = pres.addSlide();\n  slide.background = { color: C.bg };\n\n  slide.addText(\"Five Takeaways Shaping the 2025 Internet Outlook\", {\n    x: 0.5, y: 0.25, w: 9.0, h: 0.55,\n    fontSize: 26, fontFace: \"Georgia\", bold: true, color: C.white, margin: 0\n  });\n\n  const takeaways = [\n    {\n      num: \"01\",\n      title: \"Traffic Growth Trajectory\",\n      body: \"17% global growth with Starlink's 3.3x surge signals expanding connectivity reach — satellite Internet is closing the access gap.\"\n    },\n    {\n      num: \"02\",\n      title: \"Post-Quantum Momentum\",\n      body: \"Encryption adoption leapt from 2% to 13% of TLS 1.3 traffic. Browser-driven defaults are accelerating the quantum-ready transition.\"\n    },\n    {\n      num: \"03\",\n      title: \"Connectivity Fragility\",\n      body: \"Government-directed shutdowns caused 116+ of 225 disruptions. Political actions remain the single largest threat to Internet availability.\"\n    },\n    {\n      num: \"04\",\n      title: \"Persistent Security Threats\",\n      body: \"6.5% of traffic mitigated, Log4j still exploited after 3 years, and 4.3% of emails were malicious — legacy vulnerabilities endure.\"\n    },\n    {\n      num: \"05\",\n      title: \"Evolving Developer Ecosystem\",\n      body: \"Go became the top API client language (~12%), HTTP/3 reached 21% adoption — the infrastructure stack is actively modernizing.\"\n    }\n  ];\n\n  const startY = 1.05;\n  const cardH = 0.72;\n  const gap = 0.15;\n\n  takeaways.forEach((t, i) => {\n    const y = startY + i * (cardH + gap);\n\n    // Card background\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0.5, y: y, w: 9.2, h: cardH,\n      fill: { color: C.statBg }, rectRadius: 0.06\n    });\n\n    // Number accent\n    slide.addText(t.num, {\n      x: 0.7, y: y, w: 0.7, h: cardH,\n      fontSize: 22, fontFace: \"Georgia\", bold: true, color: C.accent, valign: \"middle\", margin: 0\n    });\n\n    // Title + body\n    slide.addText([\n      { text: t.title, options: { bold: true, color: C.white, fontSize: 14, fontFace: \"Calibri\" } },\n      { text: \"\\n\" + t.body, options: { color: C.light, fontSize: 11, fontFace: \"Calibri\" } },\n    ], {\n      x: 1.5, y: y, w: 7.9, h: cardH,\n      valign: \"middle\", margin: 0\n    });\n  });\n\n  // Bottom tagline\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.15, y: 5.15, w: 0.06, h: 0.35,\n    fill: { color: C.accent }\n  });\n  slide.addText(\"Source: Cloudflare Radar 2024 Year in Review  |  radar.cloudflare.com\", {\n    x: 0.5, y: 5.15, w: 9.0, h: 0.35,\n    fontSize: 9, fontFace: \"Calibri\", color: C.midGray, margin: 0\n  });\n}\n\n// ─────────────────────────────────────────────\n// Write file\n// ─────────────────────────────────────────────\nconst outPath = \"/app/output/final_deck.pptx\";\npres.writeFile({ fileName: outPath }).then(() => {\n  console.log(\"Presentation saved to \" + outPath);\n}).catch(err => {\n  console.error(\"Error:\", err);\n});\n", "numLines": 601, "startLine": 1, "totalLines": 601}}

