const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Cloudflare Radar";
pres.title = "Cloudflare Radar 2024 Year in Review";

// Color palette — Cloudflare Radar dark aesthetic
const C = {
  bg:        "0D1B3E",  // deep navy background
  bgCard:    "1A2548",  // card navy
  accent:    "F6821F",  // Cloudflare orange
  accentDim: "D46A12",  // darker orange
  white:     "FFFFFF",
  light:     "C8CDD3",  // light gray text
  midGray:   "8B95A5",  // medium gray
  darkText:  "0D1B3E",  // dark text for light cards
  statBg:    "162040",  // stat card bg
  tableBg:   "1A2548",
  tableHdr:  "F6821F",
  tableAlt:  "14213A",
  green:     "22C55E",
  red:       "EF4444",
  teal:      "0EA5E9",
};

const assetsDir = "/app/benchmark/assets";

function imgBase64(filename) {
  const p = path.join(assetsDir, filename);
  if (!fs.existsSync(p)) return null;
  const data = fs.readFileSync(p);
  const ext = path.extname(filename).replace(".", "");
  return `image/${ext === "jpg" ? "jpeg" : ext};base64,${data.toString("base64")}`;
}

const starlinkImg     = imgBase64("starlink-traffic-growth-2024.jpg");
const topServicesImg  = imgBase64("top-10-internet-services.jpg");
const postQuantumImg  = imgBase64("post-quantum-encryption-adoption.jpg");
const disruptionImg   = imgBase64("internet-disruption-causes.jpg");

// ─────────────────────────────────────────────
// SLIDE 1 — Title Slide
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.bg };

  // Large accent shape — left bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.15, h: 5.625, fill: { color: C.accent }
  });

  // Subtle bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.15, y: 5.1, w: 9.85, h: 0.06, fill: { color: C.accent }
  });

  // Title
  slide.addText("Cloudflare Radar 2024", {
    x: 0.8, y: 1.3, w: 8.5, h: 1.0,
    fontSize: 44, fontFace: "Georgia", bold: true, color: C.white, margin: 0
  });

  slide.addText("Year in Review", {
    x: 0.8, y: 2.2, w: 8.5, h: 0.8,
    fontSize: 40, fontFace: "Georgia", color: C.accent, margin: 0
  });

  // Subtitle
  slide.addText("Internet patterns and trends observed through\nCloudflare's global network during 2024", {
    x: 0.8, y: 3.3, w: 7.0, h: 0.9,
    fontSize: 16, fontFace: "Calibri", color: C.light, lineSpacingMultiple: 1.3, margin: 0
  });

  // Date
  slide.addText("2024 Annual Report", {
    x: 0.8, y: 4.6, w: 3, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: C.midGray, margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 2 — 17% Global Traffic Growth and Starlink's 3.3x Surge
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.bg };

  // Title
  slide.addText("17% Global Traffic Growth and Starlink's 3.3x Surge", {
    x: 0.5, y: 0.25, w: 9.0, h: 0.55,
    fontSize: 26, fontFace: "Georgia", bold: true, color: C.white, margin: 0
  });

  // Left column — stat callouts
  // Stat card 1 — 17%
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 4.0, h: 1.3,
    fill: { color: C.statBg }, rectRadius: 0.08
  });
  slide.addText("17%", {
    x: 0.7, y: 1.15, w: 1.8, h: 0.8,
    fontSize: 48, fontFace: "Georgia", bold: true, color: C.accent, margin: 0
  });
  slide.addText("Year-over-year global\nInternet traffic growth", {
    x: 2.5, y: 1.25, w: 1.9, h: 0.9,
    fontSize: 13, fontFace: "Calibri", color: C.light, margin: 0
  });

  // Stat card 2 — 3.3x
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 2.65, w: 4.0, h: 1.3,
    fill: { color: C.statBg }, rectRadius: 0.08
  });
  slide.addText("3.3x", {
    x: 0.7, y: 2.7, w: 1.8, h: 0.8,
    fontSize: 48, fontFace: "Georgia", bold: true, color: C.teal, margin: 0
  });
  slide.addText("SpaceX Starlink traffic\nsurge in 2024", {
    x: 2.5, y: 2.8, w: 1.9, h: 0.9,
    fontSize: 13, fontFace: "Calibri", color: C.light, margin: 0
  });

  // Additional context
  slide.addText([
    { text: "41%", options: { bold: true, color: C.accent, fontSize: 14 } },
    { text: " of global traffic from mobile devices", options: { color: C.light, fontSize: 13 } },
    { text: "\n28%", options: { bold: true, color: C.accent, fontSize: 14 } },
    { text: " IPv6 adoption of dual-stack traffic", options: { color: C.light, fontSize: 13 } },
  ], {
    x: 0.5, y: 4.2, w: 4.0, h: 0.8, fontFace: "Calibri", margin: 0
  });

  // Right column — Starlink chart image
  if (starlinkImg) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 4.85, y: 1.1, w: 4.9, h: 3.7,
      fill: { color: C.statBg }, rectRadius: 0.08
    });
    slide.addImage({
      data: starlinkImg,
      x: 5.0, y: 1.25, w: 4.6, h: 3.4,
      sizing: { type: "contain", w: 4.6, h: 3.4 }
    });
  }

  // Caption
  slide.addText("Source: Cloudflare Radar  |  Normalized Starlink traffic scaled to peak request volume", {
    x: 0.5, y: 5.15, w: 9.0, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: C.midGray, margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 3 — Google Leads Top 10 Services as Generative AI Rises
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.bg };

  slide.addText("Google Leads Top 10 Services as Generative AI Rises", {
    x: 0.5, y: 0.25, w: 9.0, h: 0.55,
    fontSize: 26, fontFace: "Georgia", bold: true, color: C.white, margin: 0
  });

  // Left — table
  const tableData = [
    [
      { text: "Rank", options: { fill: { color: C.accent }, color: C.white, bold: true, fontSize: 12, align: "center", fontFace: "Calibri" } },
      { text: "Service", options: { fill: { color: C.accent }, color: C.white, bold: true, fontSize: 12, align: "left", fontFace: "Calibri" } },
    ],
    ...([
      ["#1","Google"],["#2","Facebook"],["#3","Apple"],["#4","TikTok"],
      ["#5","AWS"],["#6","Microsoft"],["#7","Instagram"],["#8","YouTube"],
      ["#9","Amazon"],["#10","WhatsApp"]
    ].map((row, i) => row.map(cell => ({
      text: cell,
      options: {
        fill: { color: i % 2 === 0 ? C.tableAlt : C.tableBg },
        color: C.white, fontSize: 12, fontFace: "Calibri",
        align: cell.startsWith("#") ? "center" : "left"
      }
    }))))
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.1, w: 3.2, colW: [0.8, 2.4],
    border: { pt: 0.5, color: "0F1938" },
    rowH: [0.32, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28]
  });

  // Right — image
  if (topServicesImg) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 4.0, y: 1.1, w: 5.7, h: 3.1,
      fill: { color: C.statBg }, rectRadius: 0.08
    });
    slide.addImage({
      data: topServicesImg,
      x: 4.1, y: 1.2, w: 5.5, h: 2.9,
      sizing: { type: "contain", w: 5.5, h: 2.9 }
    });
  }

  // Generative AI callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.4, w: 9.2, h: 0.65,
    fill: { color: C.statBg }, rectRadius: 0.06
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.4, w: 0.08, h: 0.65,
    fill: { color: C.accent }
  });
  slide.addText([
    { text: "Generative AI ", options: { bold: true, color: C.accent, fontSize: 14 } },
    { text: "continued its rapid rise throughout 2024, while the Metaverse receded into the background. ", options: { color: C.light, fontSize: 13 } },
    { text: "Rankings based on Cloudflare 1.1.1.1 DNS resolver data.", options: { color: C.midGray, fontSize: 11, italic: true } },
  ], {
    x: 0.8, y: 4.4, w: 8.7, h: 0.65, fontFace: "Calibri", valign: "middle", margin: 0
  });

  slide.addText("Source: Cloudflare Radar 2024", {
    x: 0.5, y: 5.15, w: 9.0, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: C.midGray, margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 4 — Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.bg };

  slide.addText("Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3", {
    x: 0.5, y: 0.25, w: 9.0, h: 0.55,
    fontSize: 24, fontFace: "Georgia", bold: true, color: C.white, margin: 0
  });

  // Left — image
  if (postQuantumImg) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: 1.1, w: 5.2, h: 2.8,
      fill: { color: C.statBg }, rectRadius: 0.08
    });
    slide.addImage({
      data: postQuantumImg,
      x: 0.6, y: 1.2, w: 5.0, h: 2.6,
      sizing: { type: "contain", w: 5.0, h: 2.6 }
    });
  }

  // Right — stat cards
  // PQ Encryption card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.0, y: 1.1, w: 3.8, h: 1.2,
    fill: { color: C.statBg }, rectRadius: 0.08
  });
  slide.addText("2%  →  13%", {
    x: 6.2, y: 1.1, w: 2.2, h: 0.65,
    fontSize: 30, fontFace: "Georgia", bold: true, color: C.accent, margin: 0
  });
  slide.addText("Post-quantum encrypted TLS 1.3 traffic after Chrome 124 default enablement (Apr 17)", {
    x: 6.2, y: 1.72, w: 3.4, h: 0.55,
    fontSize: 11, fontFace: "Calibri", color: C.light, margin: 0
